import{_ as S,c as a,o as t,j as n}from"./chunks/framework.Ch_PcVtW.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/Management2/PART2/19.md","filePath":"ja-jp/Management2/PART2/19.md"}'),o={name:"ja-jp/Management2/PART2/19.md"};function B(M,e,r,s,E,G){return t(),a("div",null,[...e[0]||(e[0]=[n("p",null,"► 2023/10 日本のエンタメを更新したかった 2度目の「BMSG FES」 #BMSGFES #変革 #ライブ演出 「BMSGが考えるエンタテインメントの形を打ち出し、 日本のエンタテインメントの更新をしたかった」 「BMSG FES'23」が2023年9月23日・24日に東京・東京体育館で、 9月 • 30日 10月1日に大阪・大阪城ホールで開催された。 昨年の初開催では、 BMSG の立ち上げから Novel Core との出会い、 THE FIRST BE:FIRST の結 成など、2年間の足跡を中心に物語を紡ぎ上げるようなフェスだった。2度 目となる今回に新たに注力したのは何だったのか。 改めてそのテーマから聞 いた。 昨年のフェスは、まさにストーリーの回収のためのもの。 そこま で応援してくれていた人ほど、強くストーリーを体感できるエモーシ ョナルな良いものになったなと感じてくれたと思います。同様に、今 年もストーリーの回収は最低限やらなくてはいけないものではありま したが、シンプルな回収以上に、 BMSGが考えるエンタテインメ ントの形を打ち出し、 日本のエンタテインメントの更新をしたいと 考えました。 日本で「エンタテインメント」 という言葉を使うときには、どうし ても派手な演出やフィクション性の強いもの、ファンタジーのよう 129 なものを強く意味しすぎているように思います。 要は、フィジカルが抜けている。 本来、エンタテインメントって、 もっとエンパワーメント的な要素も含めて、人々の暮らしを良くする ためにあるもので、 現実逃避のためのものではないと思うんです。 そのために必要なのが、 マンパワー。 つまり、 人間が輝いている 瞬間を高いレベル、高いクオリティーで作ること。 起業当時から、 そこはすごく頑張ってきたことです。 具体的に言えば、ボーイズグループはニーズに合わせて作ら れたものを完璧に演じる人たちではなく、 自由意志を持って表現 したいものを突き詰める存在であるべきです。一方でソロアーティ ストにしても、全てにおいてナラティブ (語り手視点で語られる物語)が 絶対に必要だと思います。 だから、ストーリーの回収以上のもの が不可欠でしたし、個々がナラティブを背負ったうえで、それをど う美しく映像に収めるか、 その技術を更新していくかが、プレーヤ ーとスタッフが考えるべき今回の大きなテーマでした。 フェスをご覧になった方々から、スーパーボウル (アメリカンフット ボールの最高峰の大会である、NFLの優勝決定戦)のハーフタイムショー みたいだ、と言われましたが、 それを狙ったというよりは、結果とし て近いものになったというほうが正しいでしょう。 スーパーボウル のハーフタイムショーは、あくまでも音楽が中心にある演出なので、 音楽を鳴らすことを大事にしたBMSG FESも同じ方向性のもので あることは確かです。 日本のエンタテインメントはそこが抜け落ち がちなので、真新しく感じていただけた結果、 スーパーボウルみ たいだと思っていただけたのでしょうし、自分としてもやりがいを強 く感じます。 「映像」に挑戦し続ける理由 前述のように、今回注力した1つが 「映像」 だ。 BMSG が映像にプライオリ ティーを置いていることは、アーティストのMV (ミュージックビデオ)や 「 D. U.N.K.」 などにも現れているが、「今後もクオリティーの進化を続けていかな くては」と語る。 K-POPがなぜ世界中にファンがいるのかというと、その一翼を 担っているのが映像のクオリティーの高さです。もっとも、海を越え て広げるために映像が不可欠だったから、クオリティーが独自の 進化をしたとも言えるでしょう。 日本でも(グローバルを目指すなら)当 たり前のようにやらなくてはいけないことのような気がします。 今回のフェスで力を入れたのは、2つ。 1つは、照明とかも含 めて抜けたときの絵が面白いこと、もう1つはステージ上でのジン バル(動画撮影に使用する手ぶれ補正装置) 撮影にこだわりました。 「D. U.N.K.」ではドローン撮影をいろいろ試しましたし、今回も導入し ましたが、今回、特に頑張ったのはジンバル撮影ですね。映画 館や配信で見る人だけでなく、会場にいる人にとっても肉眼よりジ ンバル撮影のほうが臨場感があると思いますし、そうした映像のク オリティーが高ければ高いほど、最終的にはアーティスト自身の歌 唱とかダンスとかのプリミティブな瞬間がより映えると思うんです。 ステージの裏側から間近でアーティストそれぞれのパフォーマンスを見たが、 歌いながらカメラマンとコミュニケーションを取っている様子も印象的だった。 カメラクルーにやる気になってもらうことは大事ですね。そうでな いと、こちら側のオーダーも多くなるし、修正も大変。 実際に怒号 や罵声が飛び交う現場も少なくないと聞きますが、そんなことをせず 131 に、楽しく忌憚なく意見交換できる空気作りは大事にしました。リ ハーサルで、勉強がてら来ていた若いカメラマンが入ったんです が、僕は結構気を使うほうなんで、 相手の顔色をうかがいながら いろんなオーダーを出していたんです。そうしたら、「もっとくれ」み たいな顔をしていたので、ぐいぐいお願いして(笑)。 リハ段階で何 回か失敗もするんですが、「もう1回」 とポジティブな空気感ででき たうえに、すごくキラキラした目をしていたんですよ。そのまま本番 の全公演、彼にお願いしました。 そうしたコミュニケーションが嫌な空気にならずにできるのは、 自分の性格もありますが、 BMSGが起業から数年の会社であるこ と、アーティストも若い新人が多いっていうことなどもプラスに働いて いると思います。 あと、アーティスト本人も、いいものを作ることに対 してみんな前向きで、自分は 「大人の文化祭」という言葉をずっ と大事にしているんですが、 その空気でできていることも大きいと思 います。 自分のマネジメントが成功していると誇れる部分でもありま すね。 会場の天井からは、BMSG EAST チームの陣地であるステージ上手には大き な太陽、BMSG WESTチームの下手には月のモチーフが飾られていた。映 像には皆既日食のようなモチーフも出てきた。EAST と WEST の2チーム制、 それぞれの楽曲やMVなどに隠された裏テーマは何だったのか。 見ている方には伝わらなくてもいいものですが、プロデュースに あたって設定したものはあります。 太陽の国と月の国の2つの世 界に住む人々がいるけれども、彼らは決して交わることがないままそ れぞれに暮らしているんです。 でも、60年に1度、 月と太陽が同 時に上る日があり、 その時だけは両方の住民が邂逅し、大きな お祭りが開かれるんです。 EAST と WESTのチームは、それぞれ 132 新したかった2度目の「BMSG FES 太陽の国と月の国を代表して、コロッセオみたいな場所で開催さ れる何かの対抗戦に出ているようなもの。戦う、というよりはJリー グやNBAのオールスター戦っぽいイベントですね。 こうした設定を、ライブを担当するチームとの打ち合わせで共有 して、みんなに動いてもらいます。チームとしての経験が蓄積され てきたので、自分が関わらないと進まないことも減ってきましたし、 今、本当に助かっています。 あと、強力なスタッフが最近クリエーティブディレクターとして正 式にBMSGに加入したことも大きいです。 前回のフェスの際、 終 演後の帰り道でもお客さんにライブの世界観を感じてほしくて、壁 にプロジェクターでイメージ映像を映し出したり、 提灯を掲げたり したんですが、 その手伝いをしてもらったところから関係が始まって、 そのときは外注スタッフとしてお願いしたのですが、 フェス後、 「天 啓がありました。僕はもっとBMSGにコミットしなくちゃいけないと思 ったんですけど、何か手伝えることはありますか?」 と言ってくれて。 それで軽くお願いごとをしてみたら、「クリエーティブディレクターっ てこんなことができるのか!」が本当に多くて。 クリエーティブに関 して、自分のタッチ数が半分になって、自分のタッチポイントが 2倍になった感覚があります。 今回の設定を太陽の国と月の国にしようと思ったのもそのスタッ フとの会話の延長だし、 僕が設定を話すと、 「邂逅するのは何年 に1回ですか?」 「どんな祭りですか?」と質問してくれるからいろ いろ具体的になるし、それを膨らませたアイデアを出してくれる。 設 定を話した翌日に軽いスケッチを出してくれるのも、イメージのす り合わせができるのでありがたいですね。 23年の手応えで来年以降に自信 約5時間にも及んだライブだったが、あっという間に時間が過ぎた。 シーム レスなセットリストにもその理由がありそうだ。 予定より長くなったのは、いざアーティストたちがステージに立 つと、しゃべりたいことがたくさんあったようで。 それはうれしいこと ですが、単純計算で23人全員が2分多く話すと46分延びるわけ です(笑)。 セットリストを作るときに大事にしたのもナラティブであり、あとは シームレスであることでした。 コアや Shota (Aile The Shota)のパー トはそれぞれにおまかせしながら、 最初と最後だけは極力前後と シームレスにつながるように調整して。 面白いコラボ曲がまだいっ ぱいあるので、こうしたシームレス性は、 まだまだ進化してくんじゃ ないかな。 気が早いかもしれないが、 今年のBMSG FESの手応えを得た今、来年以降 はどんな形にしようと考えているのだろうか。 前回は、フェスを意識してそれまでの2年間を進めてきたことも あって、起業からそこまでのルートが正しければどう転んでもエモ くなりますし、企画に2年間を費やして来られたわけです。でも、今 回は思い描いていたストーリーを現実にするだけじゃなくて、現在 進行形で起こっているストーリーをステージに投影していくっていう 作業になるから、そこは大変でした。 それでもあのクオリティーの のが作れたので安心しましたし、 当面の強みになると思います。よ し、毎年できるな ! と 134 o はしたかった2度目の「BMSG FES 来年はどういう形にしようかなあ。 既に企画自体は具体的なも のがあるので楽しみにしていてください。 BMSG FES は、 どこか 特定のチームの集客力に依存せず、 全体のお客さんが来れてい る状況を作る必要があるので、もし会社として信用を得て使えると しても、ドーム規模での公演はまだタイミングではなさそうです。自 社フェスなのにオーバーキャパに感じてしまうアーティストを作るの は、もう健康的じゃないと思うからです。 来れる人を増やしたいのは確かなので、アリーナ規模でも、も のすごくタイトにして、昼夜2公演でやってもいいかもしれない。 そ の場合、フェスでしか見られないコラボを中心にして、1アーティ ストのオリジナルは1~2曲ずつにし、2時間くらいノンストップで 見せるとか。ずっとクライマックスって感じでスピード感もあるし、悪 くないかもなあ。 もちろん、様々なキャパシティーが成長するタイミングが出てき たりすれば、BMSG FES自体の在り方が変わると思いますが、少 なくとも来年は、今の「皆でやる」ファミリーコンサートのスタイル を継続しようと思っています。",-1)])])}const T=S(o,[["render",B]]);export{l as __pageData,T as default};
